FUNCTION stayFee(nights, powered)
    // stayFee: returns the total fee in dollars for a stay at the park.
    // Parameters: nights (Integer), powered (Boolean, TRUE for a powered site).
    // Nightly rate is $48 for a powered site and $36 for an unpowered site.
    // The discount is applied after the nightly total is calculated, so the 10%
    // comes off the whole stay. The test uses ≥ 7 so that a stay of exactly
    // 7 nights receives the discount.
    IF powered = TRUE THEN
        rate ← 48.00
    ELSE
        rate ← 36.00
    ENDIF
    fee ← nights * rate
    IF nights ≥ 7 THEN
        fee ← fee * 0.9
    ENDIF
    RETURN fee
ENDFUNCTION
